export async function checkout(
  businessId: string,
  cashierId: string,
  items: CartItemInput[],
  paymentMethod: string,
  received: number | null,
  orderDisc: number,
  orderDiscType: DiscountType,
  customerId: string | null = null,
): Promise<CheckoutResult> {
  if (items.length === 0) {
